"""Tensor-parallel linear layers implemented with PyTorch.

The layers follow the usual Megatron-LM convention: the full, unsharded weight
is passed in as ``master_weight`` and each rank keeps only its partition.

``ColumnParallelLinear`` shards the output dimension of the weight (the first
dimension of a ``[out_features, in_features]`` weight) and gathers the partial
outputs along the last dimension.

``RowParallelLinear`` shards the input dimension of the weight (the second
dimension of a ``[out_features, in_features]`` weight) and sums the partial
outputs across ranks.
"""

import torch
import torch.distributed as dist
import torch.nn.functional as F
from torch import nn


def _world_size():
    return dist.get_world_size() if dist.is_initialized() else 1


def _rank():
    return dist.get_rank() if dist.is_initialized() else 0


class _AllGatherLastDim(torch.autograd.Function):
    """Differentiable all_gather that concatenates along the last dimension."""

    @staticmethod
    def forward(ctx, tensor):
        world_size = _world_size()
        ctx.world_size = world_size
        ctx.rank = _rank()
        if world_size == 1:
            return tensor

        tensor = tensor.contiguous()
        gathered = [torch.empty_like(tensor) for _ in range(world_size)]
        dist.all_gather(gathered, tensor)
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.world_size == 1:
            return grad_output
        # The gathered output is replicated on every rank, so the gradient each
        # rank receives for its own partition is simply its slice of the
        # (equally replicated) output gradient.
        return grad_output.chunk(ctx.world_size, dim=-1)[ctx.rank]


class _AllReduceSum(torch.autograd.Function):
    """Differentiable all_reduce(SUM)."""

    @staticmethod
    def forward(ctx, tensor):
        world_size = _world_size()
        if world_size == 1:
            return tensor

        tensor = tensor.contiguous().clone()
        dist.all_reduce(tensor, op=dist.ReduceOp.SUM)
        return tensor

    @staticmethod
    def backward(ctx, grad_output):
        # Every rank contributes the same local gradient to the replicated
        # (summed) output, so it passes through unchanged.
        return grad_output


class ColumnParallelLinear(nn.Module):
    """Linear layer whose weight is sharded along the output dimension.

    The forward pass computes each rank's partial output and concatenates the
    partial outputs along the last dimension, yielding a replicated full
    output on every rank.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()

        if out_features % self.world_size != 0:
            raise ValueError(
                "out_features ({}) must be divisible by world_size ({})".format(
                    out_features, self.world_size
                )
            )

        self.out_features_per_partition = out_features // self.world_size

        if tuple(master_weight.shape) != (out_features, in_features):
            raise ValueError(
                "master_weight must have shape (out_features, in_features) = "
                "({}, {}), got {}".format(
                    out_features, in_features, tuple(master_weight.shape)
                )
            )

        weight = master_weight.chunk(self.world_size, dim=0)[self.rank]
        self.weight = nn.Parameter(weight.detach().contiguous().clone())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.out_features_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        output = F.linear(x, self.weight, self.bias)
        return _AllGatherLastDim.apply(output)

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}, world_size={}".format(
            self.in_features,
            self.out_features,
            self.bias is not None,
            self.world_size,
        )


